uint8_t mode_select_menu(void)
{
    uint8_t select = 0;
    extern InputState current_input;

    while(1)
    {
        Input_Read();
        Joystick_Read(&joy1_cfg, &joy1_data);
        LCD_Fill_Buffer(0);  // 统一清屏格式

        // ====================== 标题栏（和其他菜单完全一致）======================
        LCD_Draw_Rect(19, 21, 205, 28, 4, 0);
        LCD_Draw_Rect(21, 23, 205, 28, 4, 0);
        LCD_Draw_Rect(20, 22, 205, 28, 1, 0);
        // 标题阴影+文字
        LCD_printString("MODE SELECT", 35-1, 28-1, 4, 2);
        LCD_printString("MODE SELECT", 35+1, 28+1, 4, 2);
        LCD_printString("MODE SELECT", 35, 28, 1, 2);

        // ====================== 选项外框（统一风格）======================
        LCD_Draw_Rect(19-2, 70-2,  205+4, 28+4, 4, 0);
        LCD_Draw_Rect(19-2, 110-2, 205+4, 28+4, 4, 0);

        // 选中高亮框
        if(select == 0)
            LCD_Draw_Rect(19, 70, 205, 28, 1, 1);
        else
            LCD_Draw_Rect(19, 70, 205, 28, 1, 0);
        
        if(select == 1)
            LCD_Draw_Rect(19, 110, 205, 28, 1, 1);
        else
            LCD_Draw_Rect(19, 110, 205, 28, 1, 0);

        // ====================== 选项文字（统一阴影高亮）======================
        if(select == 0)
        {
            LCD_printString("SINGLE", 50-1, 80-1, 4, 2);
            LCD_printString("SINGLE", 50+1, 80+1, 4, 2);
            LCD_printString("SINGLE", 50, 80, 1, 2);
            LCD_printString("DOUBLE",  50, 120, 1, 1);
        }
        else
        {
            LCD_printString("SINGLE", 50, 80, 1, 1);
            LCD_printString("DOUBLE", 50-1, 120-1, 4, 2);
            LCD_printString("DOUBLE", 50+1, 120+1, 4, 2);
            LCD_printString("DOUBLE", 50, 120, 1, 2);
        }

        // ====================== 选择箭头（统一风格）======================
        if(select == 0)
        {
            LCD_printString(">", 5, 85, 1, 1);
            LCD_printString("<", 215, 85, 1, 1);
        }
        else
        {
            LCD_printString(">", 5, 125, 1, 1);
            LCD_printString("<", 215, 125, 1, 1);
        }

        // ====================== 按键提示（统一格式）======================
        LCD_printString("BTN2=OK    BTN3=BACK", 40, 220, 1, 1);

        LCD_Refresh(&cfg0);

        // 摇杆控制（不变）
        if(joy1_data.y_processed < -200) { select = 0; HAL_Delay(200); }
        if(joy1_data.y_processed > 200) { select = 1; HAL_Delay(200); }

        // 按键确认/返回（不变）
        if(current_input.btn2_pressed)
        {
            current_input.btn2_pressed = 0;
            return select;
        }
        if(current_input.btn3_pressed)
        {
            current_input.btn3_pressed = 0;
            return 0xFF;
        }
    }
}

void Draw_Main_Menu(void)
{
    LCD_Fill_Buffer(0); 

    // 标题边框（和你其他菜单一模一样的样式）
    LCD_Draw_Rect(19, 21, 205, 28, 4, 0);
    LCD_Draw_Rect(21, 23, 205, 28, 4, 0);
    LCD_Draw_Rect(20, 22, 205, 28, 1, 0);

    // 标题阴影 + 正文（和你其他菜单完全统一）
    LCD_printString("GAME MODE", 45-1, 28-1, 4, 2);
    LCD_printString("GAME MODE", 45+1, 28+1, 4, 2);
    LCD_printString("GAME MODE", 45, 28, 1, 2);

    // 选项外框（统一风格）
    LCD_Draw_Rect(19-2, 70-2,  205+4, 28+4, 4, 0);
    LCD_Draw_Rect(19-2, 110-2, 205+4, 28+4, 4, 0);

    // 选项1：单人
    if(menuSelect == 0)
        LCD_Draw_Rect(19, 70, 205, 28, 1, 1);  // 选中高亮
    else
        LCD_Draw_Rect(19, 70, 205, 28, 1, 0);

    // 选项2：双人
    if(menuSelect == 1)
        LCD_Draw_Rect(19, 110, 205, 28, 1, 1);
    else
        LCD_Draw_Rect(19, 110, 205, 28, 1, 0);

    // 文字（统一阴影高亮风格）
    if(menuSelect == 0)
    {
        LCD_printString("SINGLE", 50-1, 80-1, 4, 2);
        LCD_printString("SINGLE", 50+1, 80+1, 4, 2);
        LCD_printString("SINGLE", 50, 80, 1, 2);
        LCD_printString("DOUBLE",  50, 120, 1, 1);
    }
    else
    {
        LCD_printString("SINGLE", 50, 80, 1, 1);
        LCD_printString("DOUBLE", 50-1, 120-1, 4, 2);
        LCD_printString("DOUBLE", 50+1, 120+1, 4, 2);
        LCD_printString("DOUBLE", 50, 120, 1, 2);
    }

    if(menuSelect == 0)
    {
        LCD_printString(">", 5, 85, 1, 1);
        LCD_printString("<", 215, 85, 1, 1);
    }
    else
    {
        LCD_printString(">", 5, 125, 1, 1);
        LCD_printString("<", 215, 125, 1, 1);
    }

    // 统一提示文字
    LCD_printString("BTN3=BACK  PC3=OK", 40, 220, 1, 1);

    LCD_Refresh(&cfg0);  // 必须加！
}
void Menu_Control(void)
{
    // 上下选择
    if(joy1_data.y_processed < -200)
    {
        menuSelect = 0;
        HAL_Delay(200);
    }
    if(joy1_data.y_processed > 200)
    {
        menuSelect = 1;
        HAL_Delay(200);
    }

    // 按下确认 (PC3)
    if(HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_3) == GPIO_PIN_RESET)
    {
        HAL_Delay(50);
        if(HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_3) == GPIO_PIN_RESET)
        {
            if(menuSelect == 0)
                currentGameState = GAME_SINGLE;
            else
                currentGameState = GAME_DOUBLE;
        }
    }
}
uint8_t Key_Pressed(void)
{
    if (HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_2) == GPIO_PIN_RESET)
    {
        HAL_Delay(20);
        if (HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_2) == GPIO_PIN_RESET)
        {
            while (HAL_GPIO_ReadPin(GPIOC, GPIO_PIN_2) == GPIO_PIN_RESET);
            return 1;
        }
    }
    return 0;
}

void camera_shake(uint8_t strength) {
    shake_timer = strength;
}

void draw_stickman_left(int x, int y) {
    LCD_Draw_Circle(x, y-18, 5, COLOR_WHITE, 0);

    if (ai_swing == SWING_HIT || ai_swing == SWING_FOLLOW) {
        LCD_Draw_Line(x, y-12, x+2, y+9, COLOR_WHITE);
    } else {
        LCD_Draw_Line(x, y-12, x, y+9, COLOR_WHITE);
    }

    LCD_Draw_Line(x, y-8, x+10, y-2, COLOR_WHITE);

    switch(ai_swing) {
        case SWING_IDLE:
            LCD_Draw_Line(x, y-8, x-12, y-4, COLOR_WHITE);
            LCD_Draw_Line(x-12, y-4, x-22, y+8, COLOR_BLACK);
            LCD_Draw_Circle(x-22, y+8, 6, COLOR_BLACK, 0);
            break;
        case SWING_PREPARE:
            LCD_Draw_Line(x, y-8, x-8, y-9, COLOR_WHITE);
            LCD_Draw_Line(x-8, y-9, x-16, y-14, COLOR_BLACK);
            LCD_Draw_Circle(x-16, y-14, 6, COLOR_BLACK, 0);
            break;
        case SWING_PULL:
            LCD_Draw_Line(x, y-8, x-10, y-13, COLOR_WHITE);
            LCD_Draw_Line(x-10, y-13, x-20, y-20, COLOR_BLACK);
            LCD_Draw_Circle(x-20, y-20, 6, COLOR_BLACK, 0);
            break;
        case SWING_UP:
            LCD_Draw_Line(x, y-8, x-12, y-17, COLOR_WHITE);
            LCD_Draw_Line(x-12, y-17, x-23, y-26, COLOR_BLACK);
            LCD_Draw_Circle(x-23, y-26, 6, COLOR_BLACK, 0);
            break;
        case SWING_CHARGE:
            LCD_Draw_Line(x, y-8, x-15, y-22, COLOR_WHITE);
            LCD_Draw_Line(x-15, y-22, x-27, y-30, COLOR_BLACK);
            LCD_Draw_Circle(x-27, y-30, 6, COLOR_BLACK, 0);
            break;
        case SWING_HIT:
            LCD_Draw_Line(x, y-8, x-18, y-25, COLOR_WHITE);
            LCD_Draw_Line(x-18, y-25, x-32, y-36, COLOR_BLACK);
            LCD_Draw_Circle(x-32, y-36, 6, COLOR_BLACK, 0);
            break;
        case SWING_FOLLOW:
            LCD_Draw_Line(x, y-8, x-20, y-22, COLOR_WHITE);
            LCD_Draw_Line(x-20, y-22, x-33, y-28, COLOR_BLACK);
            LCD_Draw_Circle(x-33, y-28, 6, COLOR_BLACK, 0);
            break;
        case SWING_RECOVER:
            LCD_Draw_Line(x, y-8, x-13, y-15, COLOR_WHITE);
            LCD_Draw_Line(x-13, y-15, x-24, y-20, COLOR_BLACK);
            LCD_Draw_Circle(x-24, y-20, 6, COLOR_BLACK, 0);
            break;
        case SWING_RESET:
            LCD_Draw_Line(x, y-8, x-12, y-7, COLOR_WHITE);
            LCD_Draw_Line(x-12, y-7, x-21, y-4, COLOR_BLACK);
            LCD_Draw_Circle(x-21, y-4, 6, COLOR_BLACK, 0);
            break;
    }

    if (player2_is_jumping) {
        LCD_Draw_Line(x, y+9, x-7, y+13, COLOR_WHITE);
        LCD_Draw_Line(x-7, y+13, x-10, y+19, COLOR_WHITE);
        LCD_Draw_Line(x, y+9, x+9, y+21, COLOR_WHITE);
    } else {
        int is_moving = (abs(ai_target_x - ai.x) > 2);
        
        if (is_moving) {
            ai_leg_phase = (ai_leg_phase + 2) % 16;
            float phase_rad = (ai_leg_phase / 16.0f) * 2 * 3.14159f;
            float bend = (sinf(phase_rad) + 1) / 2;
            
            if (ai_leg_phase < 8) {
                int front_x = x + 7;
                int front_len = 14 + (int)(bend * 4);
                LCD_Draw_Line(x, y+9, x+4, y+14, COLOR_WHITE);
                LCD_Draw_Line(x+4, y+14, front_x, y+9+front_len, COLOR_WHITE);
                
                int back_x = x - 7;
                int back_len = 18 - (int)(bend * 4);
                LCD_Draw_Line(x, y+9, x-3, y+15, COLOR_WHITE);
                LCD_Draw_Line(x-3, y+15, back_x, y+9+back_len, COLOR_WHITE);
            } else {
                int front_x = x - 7;
                int front_len = 14 + (int)(bend * 4);
                LCD_Draw_Line(x, y+9, x-4, y+14, COLOR_WHITE);
                LCD_Draw_Line(x-4, y+14, front_x, y+9+front_len, COLOR_WHITE);
                
                int back_x = x + 7;
                int back_len = 18 - (int)(bend * 4);
                LCD_Draw_Line(x, y+9, x+3, y+15, COLOR_WHITE);
                LCD_Draw_Line(x+3, y+15, back_x, y+9+back_len, COLOR_WHITE);
            }
        } else {
            LCD_Draw_Line(x, y+9, x-5, y+24, COLOR_WHITE);
            LCD_Draw_Line(x, y+9, x+5, y+24, COLOR_WHITE);
        }
    }
}

void draw_stickman_right(int x, int y) {
    LCD_Draw_Circle(x, y-18, 5, COLOR_WHITE, 0);

    if (current_role == ROLE_HAT) {
        LCD_Draw_Line(x-8, y-19, x+8, y-19, COLOR_WHITE);
        LCD_Draw_Line(x-8, y-18, x+8, y-18, COLOR_WHITE);
        LCD_Draw_Line(x-5, y-19, x-7, y-35, COLOR_WHITE);
        LCD_Draw_Line(x+5, y-19, x+7, y-35, COLOR_WHITE);
        LCD_Draw_Line(x-7, y-35, x+7, y-35, COLOR_WHITE);
        LCD_Draw_Line(x-7, y-34, x+7, y-34, COLOR_WHITE);
    }

    if (player_swing == SWING_HIT || player_swing == SWING_FOLLOW) {
        LCD_Draw_Line(x, y-12, x-2, y+9, COLOR_WHITE);
    } else {
        LCD_Draw_Line(x, y-12, x, y+9, COLOR_WHITE);
    }

    LCD_Draw_Line(x, y-8, x-10, y-2, COLOR_WHITE);

    switch(player_swing) {
        case SWING_IDLE:
            LCD_Draw_Line(x, y-8, x+12, y-4, COLOR_WHITE);
            LCD_Draw_Line(x+12, y-4, x+22, y+8, COLOR_BLACK);
            LCD_Draw_Circle(x+22, y+8, 6, COLOR_BLACK, 0);
            break;
        case SWING_PREPARE:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+8, y+4, COLOR_WHITE);
                LCD_Draw_Line(x+8, y+4, x+16, y+12, COLOR_BLACK);
                LCD_Draw_Circle(x+16, y+12, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+8, y-9, COLOR_WHITE);
                LCD_Draw_Line(x+8, y-9, x+16, y-14, COLOR_BLACK);
                LCD_Draw_Circle(x+16, y-14, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_PULL:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+6, y+6, COLOR_WHITE);
                LCD_Draw_Line(x+6, y+6, x+12, y+16, COLOR_BLACK);
                LCD_Draw_Circle(x+12, y+16, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+10, y-13, COLOR_WHITE);
                LCD_Draw_Line(x+10, y-13, x+20, y-20, COLOR_BLACK);
                LCD_Draw_Circle(x+20, y-20, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_UP:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+10, y+8, COLOR_WHITE);
                LCD_Draw_Line(x+10, y+8, x+18, y+14, COLOR_BLACK);
                LCD_Draw_Circle(x+18, y+14, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+12, y-17, COLOR_WHITE);
                LCD_Draw_Line(x+12, y-17, x+23, y-26, COLOR_BLACK);
                LCD_Draw_Circle(x+23, y-26, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_CHARGE:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+8, y+10, COLOR_WHITE);
                LCD_Draw_Line(x+8, y+10, x+16, y+18, COLOR_BLACK);
                LCD_Draw_Circle(x+16, y+18, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+15, y-22, COLOR_WHITE);
                LCD_Draw_Line(x+15, y-22, x+27, y-30, COLOR_BLACK);
                LCD_Draw_Circle(x+27, y-30, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_HIT:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+14, y+12, COLOR_WHITE);
                LCD_Draw_Line(x+14, y+12, x+24, y+18, COLOR_BLACK);
                LCD_Draw_Circle(x+24, y+18, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+18, y-25, COLOR_WHITE);
                LCD_Draw_Line(x+18, y-25, x+32, y-36, COLOR_BLACK);
                LCD_Draw_Circle(x+32, y-36, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_FOLLOW:
            if (player_is_lifting) {
                LCD_Draw_Line(x, y-8, x+12, y+10, COLOR_WHITE);
                LCD_Draw_Line(x+12, y+10, x+22, y+16, COLOR_BLACK);
                LCD_Draw_Circle(x+22, y+16, 6, COLOR_BLACK, 0);
            } else {
                LCD_Draw_Line(x, y-8, x+20, y-22, COLOR_WHITE);
                LCD_Draw_Line(x+20, y-22, x+33, y-28, COLOR_BLACK);
                LCD_Draw_Circle(x+33, y-28, 6, COLOR_BLACK, 0);
            }
            break;
        case SWING_RECOVER:
            LCD_Draw_Line(x, y-8, x+13, y-15, COLOR_WHITE);
            LCD_Draw_Line(x+13, y-15, x+24, y-20, COLOR_BLACK);
            LCD_Draw_Circle(x+24, y-20, 6, COLOR_BLACK, 0);
            break;
        case SWING_RESET:
            LCD_Draw_Line(x, y-8, x+12, y-7, COLOR_WHITE);
            LCD_Draw_Line(x+12, y-7, x+21, y-4, COLOR_BLACK);
            LCD_Draw_Circle(x+21, y-4, 6, COLOR_BLACK, 0);
            break;
    }

    if (is_jumping) {
        LCD_Draw_Line(x, y+9, x-7, y+13, COLOR_WHITE);
        LCD_Draw_Line(x-7, y+13, x-10, y+19, COLOR_WHITE);
        LCD_Draw_Line(x, y+9, x+9, y+21, COLOR_WHITE);
    } else {
        int16_t x_val = joy1_data.x_processed;
        int is_moving = (x_val > 60 || x_val < -60);
        
        if (is_moving) {
            if (x_val > 80) {
                player_leg_phase = (player_leg_phase + 3) % 32;
            } else if (x_val < -80) {
                player_leg_phase = (player_leg_phase - 3 + 32) % 32;
            }
            
            float rad = (player_leg_phase / 32.0f) * 6.28318f;
            float s = sinf(rad);
            float step = (s + 1.0f) * 0.5f;
            
            int leg_len = 16;
            int knee_bend_front = 3;
            int knee_bend_back = 8;
            
            if (player_leg_phase < 6) {
                LCD_Draw_Line(x, y+9, x-3, y+9 + knee_bend_front, COLOR_WHITE);
                LCD_Draw_Line(x-3, y+9 + knee_bend_front, x-8, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x+3, y+9 + knee_bend_back, COLOR_WHITE);
                LCD_Draw_Line(x+3, y+9 + knee_bend_back, x+8, y+9 + leg_len - 2, COLOR_WHITE);
            } else if (player_leg_phase < 12) {
                LCD_Draw_Line(x, y+9, x-3, y+9 + knee_bend_front, COLOR_WHITE);
                LCD_Draw_Line(x-3, y+9 + knee_bend_front, x-8, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x+3, y+9 + knee_bend_back, COLOR_WHITE);
                LCD_Draw_Line(x+3, y+9 + knee_bend_back, x+8, y+9 + leg_len - 2, COLOR_WHITE);
            } else if (player_leg_phase < 16) {
                LCD_Draw_Line(x, y+9, x+1, y+9 + 2, COLOR_WHITE);
                LCD_Draw_Line(x+1, y+9 + 2, x+4, y+9 + leg_len - 1, COLOR_WHITE);
            } else if (player_leg_phase < 20) {
                LCD_Draw_Line(x, y+9, x+2, y+9 + 4, COLOR_WHITE);
                LCD_Draw_Line(x+2, y+9 + 4, x+3, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x-2, y+9 + 4, COLOR_WHITE);
                LCD_Draw_Line(x-2, y+9 + 4, x-3, y+9 + leg_len, COLOR_WHITE);
            } else if (player_leg_phase < 24) {
                LCD_Draw_Line(x, y+9, x-1, y+9 + 2, COLOR_WHITE);
                LCD_Draw_Line(x-1, y+9 + 2, x-4, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x+1, y+9 + 2, COLOR_WHITE);
                LCD_Draw_Line(x+1, y+9 + 2, x+4, y+9 + leg_len - 1, COLOR_WHITE);
            } else if (player_leg_phase < 30) {
                LCD_Draw_Line(x, y+9, x-3, y+9 + knee_bend_front, COLOR_WHITE);
                LCD_Draw_Line(x-3, y+9 + knee_bend_front, x-8, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x+3, y+9 + knee_bend_back, COLOR_WHITE);
                LCD_Draw_Line(x+3, y+9 + knee_bend_back, x+8, y+9 + leg_len - 2, COLOR_WHITE);
            } else {
                LCD_Draw_Line(x, y+9, x-2, y+9 + 3, COLOR_WHITE);
                LCD_Draw_Line(x-2, y+9 + 3, x-6, y+9 + leg_len, COLOR_WHITE);
                LCD_Draw_Line(x, y+9, x+2, y+9 + 3, COLOR_WHITE);
                LCD_Draw_Line(x+2, y+9 + 3, x+6, y+9 + leg_len - 1, COLOR_WHITE);
            }
        } else {
            LCD_Draw_Line(x, y+9, x-5, y+24, COLOR_WHITE);
            LCD_Draw_Line(x, y+9, x+5, y+24, COLOR_WHITE);
        }
    }
}

