// 绘制所有静态元素（地板、网、装饰圆）
static void draw_static_elements(void)
{
    // ========== 地板（梯形透视效果） ==========
    int floor_top_y    = 200;
    int floor_bottom_y = 239;
    int top_width_half = 90;
    int center_x       = 120;
    int trap_left  = center_x - top_width_half;
    int trap_right = center_x + top_width_half;

    for (int y = floor_top_y; y <= floor_bottom_y; y++)
    {
        float rate = (float)(y - floor_top_y) / (floor_bottom_y - floor_top_y);
        int x1 = trap_left + (0 - trap_left) * rate;
        int x2 = trap_right + (239 - trap_right) * rate;
        LCD_Draw_Line(x1, y, x2, y, 9);   // 地板底色

        int offset = 45;
        if (y % 3 == 0) {
            int dash_x1 = x1 + offset;
            LCD_Draw_Line(dash_x1, y, dash_x1, y+1, 1);
            int dash_x2 = x2 - offset;
            LCD_Draw_Line(dash_x2, y, dash_x2, y+1, 1);
        }
    }

    // 两侧边线
    LCD_Draw_Line(trap_left, floor_top_y, trap_left, 0, 1);
    LCD_Draw_Line(trap_right, floor_top_y, trap_right, 0, 1);

    // ========== 网 ==========
    draw_net();

    // ========== 装饰圆 ==========
    LCD_Draw_Circle(120, 70, 15, 5, 0);
    LCD_Draw_Circle(95, 70, 15, 2, 0);
    LCD_Draw_Circle(145, 70, 15, 6, 0);
    LCD_Draw_Circle(107, 95, 15, 3, 0);
    LCD_Draw_Circle(133, 95, 15, 4, 0);
}
void draw_game(void)
{
    // 第一帧：一次性绘制 彩色水泥墙+彩色球网+彩色五环（永久固化）
    if (first_frame) {
        for (int y = 0; y < 240; y++) {
            for (int x = 0; x < 240; x++) {
                uint8_t color = cement_bg[y * 240 + x];
                LCD_Set_Pixel(x, y, color);
            }
        }
        first_frame = 0;
    }
    
    // 擦除区域（保持不变，解决残影）
    #define ERASE_HUMAN_W  70
    #define ERASE_HUMAN_H  85
    #define ERASE_BALL_W   16
    #define ERASE_BALL_H   16
    
    // 擦除上一帧动态物体
    if (prev_ai_x != 0 || prev_ai_y != 0) {
        Restore_Background_Area(prev_ai_x - 35, prev_ai_y - 45, ERASE_HUMAN_W, ERASE_HUMAN_H);
    }
    if (prev_player_x != 0 || prev_player_y != 0) {
        Restore_Background_Area(prev_player_x - 35, prev_player_y - 45, ERASE_HUMAN_W, ERASE_HUMAN_H);
    }
    if (prev_ball_x != 0 || prev_ball_y != 0) {
        Restore_Background_Area(prev_ball_x - 8, prev_ball_y - 8, ERASE_BALL_W, ERASE_BALL_H);
    }
    
    // 球拍残影擦除（保留）
    if (prev_ai_swing >= SWING_UP && prev_ai_swing <= SWING_FOLLOW) {
        Restore_Background_Area(prev_ai_x - 40, prev_ai_y - 48, 15, 15);
    }
    if (prev_player_swing >= SWING_UP && prev_player_swing <= SWING_FOLLOW) {
        Restore_Background_Area(prev_player_x + 25, prev_player_y - 48, 15, 15);
    }
    
    // 镜头震动
    if (shake_timer > 0) {
        shake_timer--;
        shake_offset_x = (rand() % 3) - 1;
        shake_offset_y = (rand() % 3) - 1;
    } else {
        shake_offset_x = 0;
        shake_offset_y = 0;
    }
    
    // 绘制动态物体
    draw_stickman_left(ai.x + shake_offset_x, ai.y + shake_offset_y);
    draw_stickman_right(player.x + shake_offset_x, player.y + shake_offset_y);
    draw_ball((int)ball.x + shake_offset_x, (int)ball.y + shake_offset_y);
    
    // UI绘制（不变）
    int score_box_w = 70;
    int score_box_h = 32;
    int score_x = (240 - score_box_w) / 2;
    int score_y = 12;
    draw_score_box(score_x, score_y, score_box_w, score_box_h, COLOR_BLACK);
    LCD_Draw_Rect(score_x+1, score_y+1, score_box_w-2, score_box_h-2, COLOR_BLACK, 1);
    
    int digit_w = 14;
    int space = 6;
    int total_w = digit_w + space + 6 + space + digit_w;
    int start_x = score_x + (score_box_w - total_w) / 2;
    int digit_y = score_y + 6;
    
    draw_digit(start_x-1, digit_y, ai_score, COLOR_BLUE);
    draw_digit(start_x+1, digit_y, ai_score, COLOR_BLUE);
    draw_digit(start_x, digit_y, ai_score, COLOR_YELLOW);
    
    draw_minus(start_x + digit_w + space -1, digit_y, COLOR_BLUE);
    draw_minus(start_x + digit_w + space +1, digit_y, COLOR_BLUE);
    draw_minus(start_x + digit_w + space, digit_y, COLOR_YELLOW);
    
    draw_digit(start_x + digit_w + space + 6 + space -1, digit_y, player_score, COLOR_BLUE);
    draw_digit(start_x + digit_w + space + 6 + space +1, digit_y, player_score, COLOR_BLUE);
    draw_digit(start_x + digit_w + space + 6 + space, digit_y, player_score, COLOR_YELLOW);
    
    if (game_over) {
        LCD_printString("GAME OVER", 70, 100, COLOR_WHITE, 2);
        LCD_printString("PRESS KEY TO RESTART", 35, 130, COLOR_WHITE, 1);
    }
    
    #define STAMINA_BAR_X      10
    #define STAMINA_BAR_Y      220
    #define STAMINA_BAR_W      100
    #define STAMINA_BAR_H      8
    LCD_Draw_Rect(STAMINA_BAR_X, STAMINA_BAR_Y, STAMINA_BAR_W, STAMINA_BAR_H, COLOR_WHITE, 0);
    int stamina_w = (stamina * STAMINA_BAR_W) / STAMINA_MAX;
    LCD_Draw_Rect(STAMINA_BAR_X, STAMINA_BAR_Y, stamina_w, STAMINA_BAR_H, COLOR_GREEN, 1);
    
    if (current_mode == MODE_DOUBLE) {
        #define STAMINA2_BAR_X     130
        LCD_Draw_Rect(STAMINA2_BAR_X, STAMINA_BAR_Y, STAMINA_BAR_W, STAMINA_BAR_H, COLOR_WHITE, 0);
        int stamina2_w = (stamina2 * STAMINA_BAR_W) / STAMINA_MAX;
        LCD_Draw_Rect(STAMINA2_BAR_X, STAMINA_BAR_Y, stamina2_w, STAMINA_BAR_H, COLOR_GREEN, 1);
    }
    
    LCD_Refresh(&cfg0);
    
    // 保存状态
    prev_ai_x = ai.x;
    prev_ai_y = ai.y;
    prev_player_x = player.x;
    prev_player_y = player.y;
    prev_ball_x = (int)ball.x;
    prev_ball_y = (int)ball.y;
    prev_ai_swing = ai_swing;
    prev_player_swing = player_swing;
}
#define RET_OK 0
#define RET_BACK 1
// ====================== 新增：纯图片开始界面（无任何文字，适配你的LCD驱动） ======================
// ====================== 修复后的纯图片开始界面 ======================
// ====================== 纯背景+居中黑色start文字 ======================
uint8_t start_game_menu(void)
{
    extern InputState current_input;
    // 你已经删掉start的纯背景图片数组
    extern const uint8_t start_bg[];

    while (1) {
        Input_Read();
        LCD_Fill_Buffer(0);

        // 1. 先绘制你的纯羽毛球背景图
        for (int y = 0; y < 240; y++) {
            for (int x = 0; x < 240; x++) {
                uint8_t color = start_bg[y * 240 + x];
                LCD_Set_Pixel(x, y, color);
            }
        }

        // 2. 在屏幕正中间绘制黑色start文字（带白色描边增强清晰度）
        const char* start_text = "start";
        // 水平居中：2号字体每个字符宽8像素，总宽度5*8=40，中心偏移20
        int text_x = 120 - (strlen(start_text) * 4);
        // 垂直居中：2号字体高16像素，中心偏移8
        int text_y = 112;

        // 白色描边（深灰背景上黑色文字更清晰）
        LCD_printString(start_text, text_x - 1, text_y - 1, COLOR_WHITE, 2);
        LCD_printString(start_text, text_x + 1, text_y + 1, COLOR_WHITE, 2);
        // 黑色主文字
        LCD_printString(start_text, text_x, text_y, COLOR_BLACK, 2);

        LCD_Refresh(&cfg0);

        // 按键逻辑不变
        if (current_input.btn2_pressed) {
            current_input.btn2_pressed = 0;
            HAL_Delay(50);
            return RET_OK;    
        }
        if (current_input.btn3_pressed) {
            current_input.btn3_pressed = 0;
            HAL_Delay(50);
            return RET_BACK;
        }

        HAL_Delay(30);
    }
}
