uint8_t select_level_menu(GameLevel *out_level)
{
    static uint8_t level_cursor = 0;
    extern InputState current_input;

    while (1) {
        Input_Read();
        Joystick_Read(&joy1_cfg, &joy1_data);
        LCD_Fill_Buffer(0);

        LCD_Draw_Rect(19, 21, 205, 28, 4, 0);
        LCD_Draw_Rect(21, 23, 205, 28, 4, 0);
        LCD_Draw_Rect(20, 22, 205, 28, 1, 0);
        LCD_printString("CHOOSE LEVEL", 45-1, 28-1, 4, 2);
        LCD_printString("CHOOSE LEVEL", 45+1, 28+1, 4, 2);
        LCD_printString("CHOOSE LEVEL", 45, 28, 1, 2);

        LCD_Draw_Rect(19-2, 70-2,  205+4, 28+4, 4, 0);
        LCD_Draw_Rect(19-2, 110-2, 205+4, 28+4, 4, 0);
        LCD_Draw_Rect(19-2, 150-2, 205+4, 28+4, 4, 0);

        if (level_cursor == 0) {
            LCD_Draw_Rect(19, 70, 205, 28, 1, 1);
        } else {
            LCD_Draw_Rect(19, 70, 205, 28, 1, 0);
        }

        if (level_cursor == 1) {
            LCD_Draw_Rect(19, 110, 205, 28, 1, 1);
        } else {
            LCD_Draw_Rect(19, 110, 205, 28, 1, 0);
        }

        if (level_cursor == 2) {
            LCD_Draw_Rect(19, 150, 205, 28, 1, 1);
        } else {
            LCD_Draw_Rect(19, 150, 205, 28, 1, 0);
        }

        if (level_cursor == 0) {
            LCD_printString("SIMPLE", 50-1, 80-1, 4, 2);
            LCD_printString("SIMPLE", 50+1, 80+1, 4, 2);
            LCD_printString("SIMPLE", 50, 80, 1, 2);
            LCD_printString("EASY",  50, 120, 1, 1);
            LCD_printString("HARD",  50, 160, 1, 1);
        }
        else if (level_cursor == 1) {
            LCD_printString("SIMPLE", 50, 80, 1, 1);
            LCD_printString("EASY", 50-1, 120-1, 4, 2);
            LCD_printString("EASY", 50+1, 120+1, 4, 2);
            LCD_printString("EASY", 50, 120, 1, 2);
            LCD_printString("HARD",  50, 160, 1, 1);
        }
        else {
            LCD_printString("SIMPLE", 50, 80, 1, 1);
            LCD_printString("EASY",  50, 120, 1, 1);
            LCD_printString("HARD", 50-1, 160-1, 4, 2);
            LCD_printString("HARD", 50+1, 160+1, 4, 2);
            LCD_printString("HARD", 50, 160, 1, 2);
        }

        if (level_cursor == 0) {
            LCD_printString(">", 5, 85, 1, 1);
            LCD_printString("<", 215, 85, 1, 1);
        } else if (level_cursor == 1) {
            LCD_printString(">", 5, 125, 1, 1);
            LCD_printString("<", 215, 125, 1, 1);
        } else {
            LCD_printString(">", 5, 165, 1, 1);
            LCD_printString("<", 215, 165, 1, 1);
        }

        LCD_printString("BTN2=OK  BTN3=BACK", 40, 220, 1, 1);
        LCD_Refresh(&cfg0);

        if (joy1_data.y_processed < -120) {
            if (level_cursor > 0) level_cursor--;
            HAL_Delay(150);
        }
        if (joy1_data.y_processed > 120) {
            if (level_cursor < 2) level_cursor++;
            HAL_Delay(150);
        }

        // BTN2 = 确认
        if (current_input.btn2_pressed) {
            current_input.btn2_pressed = 0;
            if (level_cursor == 0) *out_level = LEVEL_SIMPLE;
            if (level_cursor == 1) *out_level = LEVEL_EASY;
            if (level_cursor == 2) *out_level = LEVEL_HARD;
            HAL_Delay(50);
            return RET_OK;
        }

        // BTN3 = 返回（关键修复）
        if (current_input.btn3_pressed) {
            current_input.btn3_pressed = 0;
            HAL_Delay(50);
            return RET_BACK;
        }

        HAL_Delay(30);
    }
}
void init_game(void)
{
    // 玩家和AI位置
    player.x = 200;
    player.y = PLAYER_BASE_Y;
    ai.x = 40;
    ai.y = AI_BASE_Y;

    // 球的初始速度和位置（发球向AI方向）
    float vx = -1.6f - ((rand() % 7) / 10.0f);
    ball.x = 180;
    ball.y = 60;
    ball.vx = vx;
    ball.vy = -0.9f;

    // 分数清零
    player_score = 0;
    ai_score = 0;
    game_over = 0;

    // 挥拍动画状态
    player_swing = SWING_IDLE;
    ai_swing = SWING_IDLE;
    swing_timer = 0;
    ai_target_x = 40;

    // 跳跃相关
    is_jumping = 0;
    jump_velocity = 0;
    ai_is_jumping = 0;
    ai_jump_velocity = 0;

    // 玩家1体力
    stamina = STAMINA_MAX;
    stamina_recover_timer = 0;

    // 双人模式玩家2（AI位置作为玩家2位置）相关
    player2_is_jumping = 0;
    player2_jump_velocity = 0;
    stamina2 = STAMINA_MAX;
    stamina2_recover_timer = 0;
    swing_cooldown2 = 0;

    // ========== 关键：重置绘制状态 ==========
    first_frame = 1;                // 下一帧重新绘制完整水泥背景
    prev_ai_x = prev_ai_y = 0;
    prev_player_x = prev_player_y = 0;
    prev_ball_x = prev_ball_y = 0;
    LCD_Set_Palette(PALETTE_GAME);
}
MenuState Game1_Run(void)
{
    LCD_Fill_Buffer(0);
    LCD_Refresh(&cfg0);
    Boot_Animation();
    // 初始化双摇杆
    if (!joy1_cfg.setup_done) {
        Joystick_Init(&joy1_cfg);
        Joystick_Calibrate(&joy1_cfg);

        Joystick_Init(&joy2_cfg);
        Joystick_Calibrate(&joy2_cfg);
    }

    PWM_SetDuty(&pwm_cfg, 0);
    extern InputState current_input;
    if (start_game_menu() == RET_BACK) {
        return MENU_STATE_HOME;
    }
    // 模式选择
    uint8_t mode = mode_select_menu();
    if(mode == 0xFF) return MENU_STATE_HOME;
    current_mode = mode;
    
    // 角色2挥拍冷却计时
    static uint32_t swing_cooldown2_timer = 0; 
    #define SWING_COOLDOWN_TIME 100

    while (1)
    {
        if (select_role_menu(&current_role) == RET_BACK) {
            return MENU_STATE_HOME;
        }
        if (show_role_stats(current_role) == RET_BACK) {
            continue;
        }

        // 双人模式显示角色指示界面
        if (current_mode == MODE_DOUBLE)
        {
            if (show_player_position_hint() == RET_BACK) {
                continue;
            }
        }

        // 单人模式 → 难度选择
        if (current_mode == MODE_SINGLE)
        {
            if (select_level_menu(&selected_level) == RET_BACK) {
                continue;
            }
        }

        // 初始化游戏（会重置 first_frame 和 prev_* 变量）
        init_game();
        buzzer_play(800, 50);

        uint8_t in_game = 1;
        while (in_game)
        {
            uint32_t tick = HAL_GetTick();
            Input_Read();

            Joystick_Read(&joy1_cfg, &joy1_data);
            Joystick_Read(&joy2_cfg, &joy2_data);

            // 退出游戏（BTN3）
            if (current_input.btn3_pressed) {
                current_input.btn3_pressed = 0;
                PWM_SetDuty(&pwm_cfg, 0);
                LCD_Set_Palette(PALETTE_DEFAULT);
                in_game = 0;
                game_over = 0;
                break;
            }

            // 角色2挥拍冷却
            if (swing_cooldown2) {
                swing_cooldown2_timer++;
                uint32_t cooldown_frames = SWING_COOLDOWN_TIME / GAME1_FRAME_TIME_MS;
                if (swing_cooldown2_timer >= cooldown_frames) {
                    swing_cooldown2 = 0;
                    swing_cooldown2_timer = 0;
                }
            }

            if (!game_over) {
                update_player_input();

                if(current_mode == MODE_DOUBLE)
                {
                    // 双人模式：玩家2控制
                    int16_t x2_val = joy2_data.x_processed;
                    int16_t y2_val = joy2_data.y_processed;
                    int move2 = 0;
                    if (x2_val > 120) move2 = MOVE_SPEED_NORMAL;
                    else if (x2_val < -120) move2 = -MOVE_SPEED_NORMAL;
                    ai.x += move2;
                    if(ai.x < 20) ai.x = 20;
                    if(ai.x > NET_X - 20) ai.x = NET_X - 20;

                    stamina2_recover_timer++;
                    if (stamina2_recover_timer >= 2) {
                        stamina2_recover_timer = 0;
                        if (stamina2 < STAMINA_MAX) stamina2 += STAMINA_RECOVERY;
                    }

                    if (!player2_is_jumping && y2_val < -150) {
                        if (stamina2 >= STAMINA_JUMP_COST) {
                            player2_is_jumping = 1;
                            player2_jump_velocity = -JUMP_POWER_NORMAL;
                            stamina2 -= STAMINA_JUMP_COST;
                        }
                    }

                    if (player2_is_jumping) {
                        ai.y += player2_jump_velocity;
                        player2_jump_velocity += GRAVITY;
                        if (ai.y >= AI_BASE_Y) {
                            ai.y = AI_BASE_Y;
                            player2_is_jumping = 0;
                            player2_jump_velocity = 0;
                        }
                    }

                    if (current_input.btn4_pressed && ai_swing == SWING_IDLE && !swing_cooldown2) {
                        current_input.btn4_pressed = 0;
                        ai_swing = SWING_PREPARE;
                        swing_cooldown2 = 1;
                        swing_cooldown2_timer = 0;
                        buzzer_play(900, 50);
                    }
                }
                else  // 单人模式
                {
                    update_ai();
                }

                update_player_jump();
                update_swing_animation();
                check_racket_collision();
                update_ball();
            }
            else 
            {
                if (current_input.btn2_pressed) {
                    current_input.btn2_pressed = 0;
                    LCD_Set_Palette(PALETTE_DEFAULT);
                    in_game = 0;
                    game_over = 0;
                }
            }
            buzzer_update();
            fx_update();
            draw_game(); 
            while (HAL_GetTick() - tick < GAME1_FRAME_TIME_MS);
        }
    }
}